<?php
session_start();
if (empty($_SESSION['qms_logged_in'])) { header('Location: login.php'); exit; }
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/risk-functions.php';
$id=(int)($_GET['id']??0);$userId=(int)($_SESSION['qms_user_id']??0);$super=($_SESSION['qms_role']??'')==='super_admin';$risk=qmsRiskFind($pdo,$id,$userId,$super);if(!$risk){http_response_code(404);exit('Risk bulunamadı.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{qmsRiskVerifyCsrf($_POST['csrf']??null);$pdo->beginTransaction();$risk=qmsRiskFind($pdo,$id,$userId,$super,true);if(!$risk)throw new RuntimeException('Risk bulunamadı.');if((string)($risk['updated_at']??'')!==(string)($_POST['version']??''))throw new RuntimeException('Risk başka bir kullanıcı tarafından güncellendi. Sayfayı yenileyin.');$_POST['company_id']=$risk['company_id'];$data=qmsRiskValidate($_POST,[(int)$risk['company_id']],false);$stmt=$pdo->prepare('UPDATE risks SET title=?,category=?,responsible_person=?,due_date=?,status=?,description=?,existing_controls=?,treatment_plan=?,initial_likelihood=?,initial_impact=?,residual_likelihood=?,residual_impact=?,updated_by=? WHERE id=?');$stmt->execute([$data['title'],$data['category']?:null,$data['responsible_person']?:null,$data['due_date']?:null,$data['status'],$data['description'],$data['existing_controls']?:null,$data['treatment_plan']?:null,$data['initial_likelihood'],$data['initial_impact'],$data['residual_likelihood'],$data['residual_impact'],$userId,$id]);$pdo->prepare('INSERT INTO risk_history (risk_id,status,residual_likelihood,residual_impact,note,changed_by) VALUES (?,?,?,?,?,?)')->execute([$id,$data['status'],$data['residual_likelihood'],$data['residual_impact'],$data['note']?:'Risk kaydı güncellendi.',$userId]);$pdo->commit();header('Location: risk-detail.php?id='.$id.'&risk=updated');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Risk güncellenemedi.':$e->getMessage();}}
$risk=qmsRiskFind($pdo,$id,$userId,$super);$historyStmt=$pdo->prepare('SELECT h.*,u.full_name FROM risk_history h LEFT JOIN users u ON u.id=h.changed_by WHERE h.risk_id=? ORDER BY h.id DESC');$historyStmt->execute([$id]);$history=$historyStmt->fetchAll(PDO::FETCH_ASSOC);$initial=qmsRiskScore($risk['initial_likelihood'],$risk['initial_impact']);$residual=qmsRiskScore($risk['residual_likelihood'],$risk['residual_impact']);$statusLabels=['open'=>'Açık','monitoring'=>'İzlemede','treated'=>'Önlem Uygulandı','closed'=>'Kapalı'];$activeNav='risks';function rdEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="tr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QMS Risk Detayı</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/risks.css"></head><body class="has-sidebar"><?php require __DIR__.'/includes/app-sidebar.php';?><header class="topbar"><div class="topbar-inner"><div class="page-title-block"><strong data-i18n="riskDetailTitle">Risk Detayı</strong><span><?=rdEsc($risk['company_name'])?></span></div><div class="topbar-actions"><button class="topbar-button" id="languageToggle">EN</button><button class="topbar-button" id="themeToggle" aria-label="Tema değiştir">🌙</button></div></div></header><main class="page-container"><section class="page-heading page-heading-actions"><div><span class="section-kicker" data-i18n="riskWorkspaceKicker">Risk Çalışma Alanı</span><h1><?=rdEsc($risk['title'])?></h1><p><?=rdEsc($risk['company_name'])?> · <?=rdEsc($statusLabels[$risk['status']]??$risk['status'])?></p></div><a class="secondary-button" href="risks.php" data-i18n="backToRisksButton">Risklere Dön</a></section><?php if(($_GET['risk']??'')==='created'):?><div class="form-message success" data-i18n="riskCreatedMessage">Risk kaydı oluşturuldu.</div><?php endif;?><?php if(($_GET['risk']??'')==='updated'):?><div class="form-message success" data-i18n="riskUpdatedMessage">Risk kaydı güncellendi.</div><?php endif;?><?php if($error):?><div class="form-message error"><?=rdEsc($error)?></div><?php endif;?>
<section class="dashboard-grid compact-dashboard-grid">
    <div class="dashboard-card metric-blue">
        <?= appIcon("alert", "dashboard-card-icon") ?>
        <div class="dashboard-card-content"><span class="dashboard-card-label" data-i18n="initialRiskScoreLabel">Başlangıç Riski</span><strong class="dashboard-card-number risk-score risk-level-<?=qmsRiskLevel($initial)?>"><?=$initial?></strong><small><?=qmsRiskLevelLabel(qmsRiskLevel($initial))?></small></div>
    </div>
    <div class="dashboard-card metric-teal">
        <?= appIcon("check", "dashboard-card-icon") ?>
        <div class="dashboard-card-content"><span class="dashboard-card-label" data-i18n="residualRiskScoreLabel">Önlem Sonrası Risk</span><strong class="dashboard-card-number risk-score risk-level-<?=qmsRiskLevel($residual)?>"><?=$residual??'—'?></strong><small><?=qmsRiskLevelLabel(qmsRiskLevel($residual))?></small></div>
    </div>
</section>
<section class="risk-layout"><div class="form-panel"><h2 data-i18n="riskTrackingTitle">Risk Takibi</h2><form method="post" class="auditor-form"><input type="hidden" name="csrf" value="<?=rdEsc(qmsRiskCsrf())?>"><input type="hidden" name="version" value="<?=rdEsc($risk['updated_at'])?>"><div class="form-grid"><label class="form-field form-field-wide"><span data-i18n="riskTitleLabel">Risk Tanımı</span><input name="title" maxlength="255" value="<?=rdEsc($risk['title'])?>" required></label><label class="form-field"><span data-i18n="riskCategoryLabel">Kategori</span><input name="category" maxlength="100" value="<?=rdEsc($risk['category'])?>"></label><label class="form-field"><span data-i18n="responsiblePersonLabel">Sorumlu</span><input name="responsible_person" maxlength="150" value="<?=rdEsc($risk['responsible_person'])?>"></label><label class="form-field"><span data-i18n="dueDateLabel">Termin</span><input type="date" name="due_date" value="<?=rdEsc($risk['due_date'])?>"></label><label class="form-field"><span data-i18n="riskStatusLabel">Durum</span><select name="status"><?php foreach($statusLabels as $value=>$label):?><option value="<?=$value?>" <?=$risk['status']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label class="form-field form-field-wide"><span data-i18n="riskDescriptionLabel">Risk Açıklaması</span><textarea name="description" rows="4" required><?=rdEsc($risk['description'])?></textarea></label><label class="form-field form-field-wide"><span data-i18n="existingControlsLabel">Mevcut Kontroller</span><textarea name="existing_controls" rows="4"><?=rdEsc($risk['existing_controls'])?></textarea></label><label class="form-field form-field-wide"><span data-i18n="treatmentPlanLabel">Önlem Planı</span><textarea name="treatment_plan" rows="4"><?=rdEsc($risk['treatment_plan'])?></textarea></label><?php foreach(['initial_likelihood'=>'Başlangıç Olasılık','initial_impact'=>'Başlangıç Etki','residual_likelihood'=>'Önlem Sonrası Olasılık','residual_impact'=>'Önlem Sonrası Etki'] as $name=>$label):?><label class="form-field"><span><?=$label?> (1–5)</span><select name="<?=$name?>" <?=str_starts_with($name,'initial_')?'required':''?>><option value="">Seçin</option><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?=(string)$risk[$name]===(string)$i?'selected':''?>><?=$i?></option><?php endfor;?></select></label><?php endforeach;?><label class="form-field form-field-wide"><span data-i18n="trackingNoteLabel">Takip Notu</span><textarea name="note" rows="3" required></textarea></label></div><div class="form-actions"><button class="primary-button" data-i18n="saveRiskButton">Riski Kaydet</button></div></form></div><aside class="risk-matrix-panel"><h2 data-i18n="riskMatrixTitle">5×5 Risk Matrisi</h2><p data-i18n="riskMatrixHelp">Satırlar etki, sütunlar olasılıktır.</p><div class="risk-matrix"><span></span><?php for($l=1;$l<=5;$l++):?><strong>O<?=$l?></strong><?php endfor;?><?php for($impact=5;$impact>=1;$impact--):?><strong>E<?=$impact?></strong><?php for($likelihood=1;$likelihood<=5;$likelihood++):$score=$impact*$likelihood;$isInitial=$risk['initial_likelihood']==$likelihood&&$risk['initial_impact']==$impact;$isResidual=$risk['residual_likelihood']==$likelihood&&$risk['residual_impact']==$impact;?><span class="risk-matrix-cell risk-level-<?=qmsRiskLevel($score)?> <?=$isInitial?'is-initial':''?> <?=$isResidual?'is-residual':''?>" title="<?=$score?>"><?=$score?><?php if($isInitial):?><b>B</b><?php endif;?><?php if($isResidual):?><b>S</b><?php endif;?></span><?php endfor;?><?php endfor;?></div><div class="risk-legend"><span><b>B</b> Başlangıç</span><span><b>S</b> Sonrası</span></div><p class="risk-assumption">1–4 Düşük · 5–9 Orta · 10–16 Yüksek · 17–25 Kritik. Proje varsayımıdır.</p></aside></section>
<section class="page-section"><div class="section-heading"><div><h2 data-i18n="riskHistoryTitle">Takip Geçmişi</h2><p data-i18n="riskHistoryText">Durum ve kalan risk değişiklikleri.</p></div></div><?php if(!$history):?><div class="empty-state">Henüz takip kaydı yok.</div><?php else:?><div class="approval-history"><?php foreach($history as $item):$score=qmsRiskScore($item['residual_likelihood'],$item['residual_impact']);?><div class="approval-history-item"><span class="status-badge"><?=rdEsc($statusLabels[$item['status']]??$item['status'])?></span><div><strong><?=rdEsc($item['full_name']?:'—')?> · <?=$score!==null?'Puan '.$score:'Değerlendirilmedi'?></strong><span><?=rdEsc($item['note']?:'—')?> · <?=rdEsc($item['created_at'])?></span></div></div><?php endforeach;?></div><?php endif;?></section></main><script src="assets/js/theme.js"></script><script src="assets/js/language.js"></script><script src="assets/js/sidebar.js"></script><script src="assets/js/pwa.js"></script></body></html>
